  PmoaStatus() {
    this.specCount = parseInt(this.form.value.P1Left) + parseInt(this.form.value.P1Right) + parseInt(this.form.value.P2Left) + parseInt(this.form.value.P2Right) + parseInt(this.form.value.P3Left) + parseInt(this.form.value.P3Right);
    this.deicCount = parseInt(this.form.value.P4Left) + parseInt(this.form.value.P4Right) + parseInt(this.form.value.P5Left) + parseInt(this.form.value.P5Right) + parseInt(this.form.value.P6Left) + parseInt(this.form.value.P6Right) +
      parseInt(this.form.value.P7Left) + parseInt(this.form.value.P7Right) + parseInt(this.form.value.P8Left) + parseInt(this.form.value.P8Right) + parseInt(this.form.value.P9Left) + parseInt(this.form.value.P9Right) + parseInt(this.form.value.P10Left) + parseInt(this.form.value.P10Right) + parseInt(this.form.value.P11Left) + parseInt(this.form.value.P11Right) + parseInt(this.form.value.P12Left) + parseInt(this.form.value.P12Right) +
      parseInt(this.form.value.P13Left) + parseInt(this.form.value.P13Right) + parseInt(this.form.value.P14Left) + parseInt(this.form.value.P14Right) + parseInt(this.form.value.P15Left) + parseInt(this.form.value.P15Right) + parseInt(this.form.value.P16Left) + parseInt(this.form.value.P16Right);
    if (this.specCount < 12 && this.deicCount === 52) {
      this.healthStatus = 1;
    } else if (this.specCount === 12 && this.deicCount < 52) {
      this.healthStatus = 2;
    } else if (this.specCount < 12 && this.deicCount < 52) {
      this.healthStatus = 3;
    } else if ((this.specCount + this.deicCount) === 64 || (this.specCount + this.deicCount) == 0) {
      this.healthStatus = 4;
    } else {
      this.healthStatus = 0;
    }
    this.form.controls['HealthSts'].setValue(this.healthStatus);
    this.form.controls['ScrId'].setValue(this.userId);
    this.form.controls['userName'].setValue(this.userName);
    this.form.controls['screenDate'].setValue(this.momentjs().format('YYYY-MM-DD'));
  }

